import { useState } from "react";
import { Link } from "react-router-dom";
import { logo } from "../assets/home";
import Container from "./Container";

function Navbar() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <nav className="bg-[#181818]/80 backdrop-blur-lg shadow-lg sticky top-0 z-50">
      <Container>
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <div className="flex gap-4 items-center">
            <img className="h-[40px] w-[120px]" src={logo} alt="Live Hunt Share" />
          </div>

          {/* Desktop Menu */}
          <div className="hidden md:flex items-center space-x-6">
            {["Home", "Funding", "About", "Membership", "Contact"].map((item, idx) => (
              <Link
                key={idx}
                to="/"
                className="nav-link"
              >
                {item}
              </Link>
            ))}
          </div>

          {/* Login Button */}
          <Link to="/" className="hidden md:block">
            <div className="login-btn">Log In</div>
          </Link>

          {/* Mobile Menu Button */}
          <div className="md:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className={`hamburger ${isOpen ? "open" : ""}`}
            >
              <span></span>
              <span></span>
              <span></span>
            </button>
          </div>
        </div>

        {/* Mobile Menu */}
        <div
          className={`overflow-hidden transition-all duration-300 ${
            isOpen ? "max-h-[500px]" : "max-h-0"
          } md:hidden`}
        >
          <div className="px-4 pt-4 pb-6 space-y-3 text-white">
            {["Home", "Funding", "About", "Membership", "Contact"].map((item, idx) => (
              <Link
                key={idx}
                to="/"
                className="block nav-link text-lg"
              >
                {item}
              </Link>
            ))}
            <Link to="/" className="block login-btn w-full text-center">
              Log In
            </Link>
          </div>
        </div>
      </Container>
    </nav>
  );
}

export default Navbar;
